const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',truck:'<path d="M3 5h11v12H3zM14 9h4l3 4v4h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',return:'<path d="m3 10 4-4 4 4M7 6v8a6 6 0 1 0 6-6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-5"/>',leaf:'<path d="M20 3c0 12-3 17-10 17a7 7 0 0 1-7-7C3 6 12 7 20 3Z"/><path d="m4 20 11-11"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',box:'<path d="m12 3 9 5-9 5-9-5 9-5ZM3 8v10l9 4 9-4V8M12 13v9M7 5l9 5"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4c3 1 3 3 3 7"/>',tag:'<path d="M3 3h8l10 10-8 8L3 11V3Z"/><circle cx="7.5" cy="7.5" r="1"/>',settings:'<path d="m10 3-1 3-3 1-3 3v4l3 3 3 1 1 3h4l1-3 3-1 3-3v-4l-3-3-3-1-1-3h-4Z"/><circle cx="12" cy="12" r="3"/>',logout:'<path d="M10 4H4v16h6M10 12h11m-4-4 4 4-4 4"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10M10 21h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',check:'<path d="m5 12 4 4L19 6"/>',location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M21 10h-6v6h6M3 5l14-3v3"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>'};
const I=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.box}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'৳'+Number(n||0).toLocaleString(L10N.lang==='bn'?'bn-BD':'en-BD');
const date=s=>new Date(s.replace(' ','T')).toLocaleDateString(L10N.lang==='bn'?'bn-BD':'en-GB',{day:'numeric',month:'short',year:'numeric'});
function loadLocal(k){try{return JSON.parse(localStorage.getItem(k)||'[]')}catch{return []}}
const S={products:[],settings:{},user:BOOT.user,cart:loadLocal('bonon-cart'),wish:loadLocal('bonon-wish'),category:'All',search:'',sort:'featured',max:10000,page:1,tab:'All',adminTab:'overview',accountTab:'overview',charts:[],coupon:null,orders:[],admin:null};
function api(action,data){return $.ajax({url:'/api?action='+action,method:data===undefined?'GET':'POST',contentType:'application/json',data:data===undefined?undefined:JSON.stringify(data),headers:{'X-CSRF-Token':BOOT.csrf}})}
function toast(msg){$('#toast').html(I('check')+esc(msg)).addClass('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').removeClass('show'),3400)}
function fail(e){const msg=e.responseJSON?.error||'Unable to connect. Please try again.';if($('.form-error').length)$('.form-error').text(msg);else toast(msg)}
function save(){localStorage.setItem('bonon-cart',JSON.stringify(S.cart));localStorage.setItem('bonon-wish',JSON.stringify(S.wish));$('.bag-count').text(S.cart.reduce((a,b)=>a+b.qty,0));$('.wish-count').text(S.wish.length||'')}
async function refresh(){const d=await api('catalog');S.products=d.products;S.settings=d.settings;S.delivery=d.delivery;S.showcase=d.showcase;S.returnPolicy=d.return_policy;S.user=d.user;BOOT.demoLogin=d.demo_login;if(window.CMS&&d.studio)CMS.set(d.studio);S.products.forEach(p=>{if(p.name_bn)L10N.dict[p.name]=p.name_bn;if(p.description_bn)L10N.dict[p.description]=p.description_bn;});if(d.settings.announcement_bn)L10N.dict[d.settings.announcement]=d.settings.announcement_bn;S.cart=S.cart.filter(c=>S.products.some(p=>p.id===c.id));save()}
const product=id=>S.products.find(p=>p.id==id);
let logo=()=>`<a class="brand" href="#home" aria-label="BONON home">bonon<span>ROOTED IN EVERYDAY</span></a>`;
function baseHeader(){return `<div class="announcement"><span>Thoughtfully made. Joyfully worn.</span><span>${esc(S.settings.announcement||'A little joy, delivered. Free shipping on orders over ৳3,000.')} ${I('arrow')}</span><button data-action="login">${BOOT.demoLogin?'<i class="live-dot"></i> Explore demo':'My account'} ${I('arrow')}</button></div><header class="store-header"><div class="header-main wrap">${logo()}<form id="search-form" class="search-box">${I('search')}<input name="q" value="${esc(S.search)}" placeholder="Find a little something you love…" aria-label="Search products"><kbd>⌕</kbd></form><div class="header-actions"><button class="icon-button account-button" data-action="account" aria-label="My account" title="My account">${I('user')}</button><a class="icon-button" href="#wishlist" aria-label="Wishlist">${I('heart')}<sup class="wish-count">${S.wish.length||''}</sup></a><button class="icon-button" data-action="cart" aria-label="Open shopping bag">${I('bag')}<sup class="bag-count">${S.cart.reduce((a,b)=>a+b.qty,0)}</sup></button><button class="mobile-menu icon-button" data-action="mobile-menu" aria-label="Open menu">${I('menu')}</button></div></div><nav class="store-nav wrap"><a href="#shop" class="${location.hash==='#shop'?'active':''}">Shop all ${I('down')}</a><a href="#shop?cat=Women">Women</a><a href="#shop?cat=Men">Men</a><a href="#shop?cat=Kids">Kids</a><a href="#shop?cat=Home%20%26%20Living">Home & Living</a><a href="#shop?cat=Accessories">Accessories</a><a href="#shop?sort=new">New arrivals <span class="tiny-dot"></span></a><a class="sale-link" href="#shop?sale=1">The good finds <span>SALE</span></a><a class="story-nav" href="#story">Our story ${I('leaf')}</a></nav></header>`}
function footer(){return `<section class="newsletter"><div class="wrap newsletter-inner"><div><span class="eyebrow">LET’S STAY A LITTLE CLOSER</span><h2>Good things, in your inbox.</h2><p>New collections, little stories, and a few lovely surprises.</p></div><form id="newsletter-form"><div><input type="email" name="email" placeholder="Your email address" required aria-label="Email address"><button aria-label="Subscribe">${I('arrow')}</button></div><label class="newsletter-consent"><input type="checkbox" name="consent" value="1" required> I agree to receive marketing emails. I can unsubscribe.</label><small>By subscribing, you agree to our <button type="button" data-info="Privacy policy">privacy policy</button>. No spam, ever.</small></form></div></section><footer class="footer wrap"><div class="footer-main"><div>${logo()}<p>Thoughtful threads. Beautiful everyday.<br>A little closer to your roots.</p><span class="made">Made with care, in Bangladesh ${I('heart')}</span></div><div><h4>Discover</h4><a href="#shop?cat=Women">For her</a><a href="#shop?cat=Men">For him</a><a href="#shop?cat=Kids">For little ones</a><a href="#shop?cat=Home%20%26%20Living">For your home</a></div><div><h4>Here to help</h4><button data-info="Delivery & returns">Delivery & returns</button><button data-action="account">Track your order</button><button data-info="Size guide">Size guide</button><button data-info="Contact us">Contact us</button></div><div><h4>The BONON world</h4><a href="#story">Our story</a><a href="#story">Craft & community</a><button data-info="Care guide">Made to last</button><button data-action="login">${BOOT.demo?'Explore the demo':'Your account'} ${I('external')}</button></div></div><div class="footer-bottom"><span>© 2026 BONON. Thoughtfully woven, beautifully you.</span><div><button data-info="Privacy policy">Privacy</button><button data-info="Terms of use">Terms</button><span class="payment">bKash</span><span class="payment">VISA</span><span class="payment">COD</span></div></div></footer>`}
function baseCard(p){return `<article class="product-card"><div class="product-photo"><button class="image-open" data-product="${p.id}" aria-label="View ${esc(p.name)}"><img src="${p.image}" alt="${esc(p.name)}" loading="lazy"></button>${p.tag?`<span class="product-tag ${p.tag==='Bestseller'?'best':''}">${esc(p.tag)}</span>`:p.old_price?`<span class="product-tag">${Math.round((1-p.price/p.old_price)*100)}% off</span>`:''}<button class="heart-button ${S.wish.includes(p.id)?'selected':''}" data-wish="${p.id}" aria-label="Save ${esc(p.name)}">${I('heart')}</button><button class="quick-add" data-product="${p.id}">Quick look ${I('plus')}</button></div><div class="product-meta"><span>${esc(p.subcategory)}</span><div class="rating">★ <span>4.${7+p.id%3}</span></div></div><button class="product-title" data-product="${p.id}">${esc(p.name)}</button><div class="price-line"><span>${money(p.price)} ${p.old_price?`<del>${money(p.old_price)}</del>`:''}</span><span class="swatches">${p.colors.slice(0,3).map(c=>`<i style="background:${c}"></i>`).join('')}</span></div></article>`}
function benefits(){return `<div class="benefits wrap">${[['truck','A little joy, delivered','Shipping all across Bangladesh'],['return','Love it, or return it','Easy 7-day returns'],['shield','Shop with confidence','Secure checkout, always'],['leaf','Thoughtfully selected','Quality in every little detail']].map(([i,h,p])=>`<div>${I(i)}<span><strong>${h}</strong><small>${p}</small></span></div>`).join('')}</div>`}
function home(){const cats=[['Women','For every version of you','category-women'],['Men','Everyday, elevated','category-men'],['Kids','Little clothes. Big adventures.','kids-1'],['Home & Living','Make room for comfort','home-editorial'],['Accessories','It’s all in the details','bag']];return `${header()}<main><section class="hero wrap"><div class="hero-art"></div><div class="hero-copy"><div class="eyebrow"><span></span> THE EVERYDAY HERITAGE COLLECTION</div><h1>A little closer<br>to your <em>roots.</em></h1><p>Familiar threads. Fresh beginnings.<br>Thoughtful pieces for the way you live, every day.</p><a href="#shop" class="btn btn-dark">Discover the collection ${I('arrow')}</a><div class="hero-foot"><span>ROOTED IN TRADITION. MADE FOR TODAY.</span><span>01 <i></i> 03</span></div></div><div class="craft-seal">CRAFTED WITH CARE<span>বুনন</span>WORN WITH LOVE</div><div class="hero-caption">THE ART OF EVERYDAY LIVING <span>EST. 2026</span></div></section>${benefits()}<section class="section wrap"><div class="section-heading"><div><span class="eyebrow">A WORLD OF LITTLE JOYS</span><h2>Find your everyday.</h2></div><a class="text-link" href="#shop">Explore all collections ${I('arrow')}</a></div><div class="category-grid">${cats.map(([name,desc,img])=>`<a class="category-card" href="#shop?cat=${encodeURIComponent(name)}"><div class="category-image"><img src="/assets/${img}.jpg" alt="${name}" loading="lazy"><span>${I('arrow')}</span></div><h3>${name}</h3><p>${desc}</p></a>`).join('')}</div></section><section class="section featured-section wrap"><div class="section-heading"><div><span class="eyebrow">YOUR NEXT FAVORITES</span><h2>Freshly woven. Just for you.</h2></div><a class="text-link" href="#shop?sort=new">View all new arrivals ${I('arrow')}</a></div><div class="collection-tabs">${['All','Women','Men','Home & Living','Kids','Accessories'].map(c=>`<button data-tab="${c}" class="${S.tab===c?'active':''}">${c==='All'?'All the good things':c}</button>`).join('')}<span>Considered details. Effortless style.</span></div><div class="product-grid" id="featured-products">${S.products.filter(p=>S.tab==='All'||p.category===S.tab).slice(0,4).map(card).join('')}</div></section><section class="editorial wrap"><div class="editorial-image"><img src="/assets/home-editorial.jpg" alt="A calm, thoughtfully styled living space" loading="lazy"><span>THE SLOW LIVING EDIT</span></div><div class="editorial-copy"><span class="eyebrow">A SOFTER KIND OF EVERYDAY</span><h2>There’s no place<br>like <em>your home.</em></h2><p>The softest cotton. The warmest corners.<br>Little details that make a house feel like you.</p><a class="btn btn-dark" href="#shop?cat=Home%20%26%20Living">Make yourself at home ${I('arrow')}</a><span class="handwritten">Comfort, thoughtfully woven.</span></div></section><section class="section wrap"><div class="section-heading"><div><span class="eyebrow">LOVED FOR A REASON</span><h2>The everyday favorites.</h2></div><a href="#shop?sort=popular" class="text-link">Shop bestsellers ${I('arrow')}</a></div><div class="product-grid">${S.products.filter(p=>p.tag==='Bestseller').slice(0,4).map(card).join('')}</div></section><section class="brand-note wrap"><span class="eyebrow">MORE THAN WHAT WE WEAR</span><h2>Our roots run deep.<br>Our story is <em>still being woven.</em></h2><p>Inspired by the warmth of Bangladesh, we bring together the familiar and the new.<br>Honest materials, thoughtful details, and a little bit of home in everything we do.</p><a href="#story" class="text-link">Get to know BONON ${I('arrow')}</a><div class="note-flower">✳</div></section></main>${footer()}`}
function catalogBudget(){let min=Infinity,max=-Infinity;for(const p of S.products){if(p.active!==undefined&&+p.active!==1||p.price==null||p.price==='')continue;const n=Number(p.price);if(Number.isFinite(n)&&n>=0){min=Math.min(min,n);max=Math.max(max,n)}}return min===Infinity?{min:0,max:0,empty:true}:{min,max,empty:false}}
function syncBudget(reset=false){const b=catalogBudget(),all=reset||S.budgetTop===undefined||S.max>=S.budgetTop;S.max=all?b.max:Math.max(b.min,Math.min(S.max,b.max));S.budgetTop=b.max;$('#budget').attr({min:b.min,max:b.max,step:'any'}).prop('disabled',b.empty||b.min===b.max).val(S.max);$('#budget-value').text(money(S.max));$('#budget-min').text(money(b.min));$('#budget-max').text(money(b.max));return b}
function shop(wishlist=false){const bounds=catalogBudget();let params=new URLSearchParams(location.hash.split('?')[1]||'');let cat=params.get('cat')||'All';let q=params.get('q')||'';if(!S.shopInit||S.shopKey!==location.hash){S.category=cat;S.search=q;S.sort=params.get('sort')||'featured';S.max=bounds.max;S.budgetTop=bounds.max;S.page=1;S.shopInit=true;S.shopKey=location.hash}syncBudget();return `${header()}<main class="wrap shop-page"><div class="breadcrumbs"><a href="#home">Home</a>${I('chevron')}<span>${wishlist?'Wishlist':cat==='All'?'All collections':esc(cat)}</span></div><div class="shop-intro"><span class="eyebrow">${wishlist?'SAVED WITH LOVE':'THOUGHTFULLY CURATED, JUST FOR YOU'}</span><h1>${wishlist?'Your little favorites.':q?'A little something for “'+esc(q)+'”.':cat==='All'?'The everyday collection.':esc(cat)+', thoughtfully made.'}</h1><p>${wishlist?'The pieces you keep coming back to.':'Find pieces to love today, tomorrow, and all the days after.'}</p></div><div class="shop-layout">${wishlist?'':`<aside class="shop-filters"><div class="filter-heading">Filter by <button data-action="reset-filters">Reset</button></div><h4>Collections</h4>${['All','Women','Men','Kids','Home & Living','Accessories'].map(c=>`<label class="radio-row"><input type="radio" name="category" value="${c}" ${S.category===c?'checked':''}><span>${c==='All'?'All collections':c}</span><small>${S.products.filter(p=>c==='All'||p.category===c).length}</small></label>`).join('')}<div class="filter-block"><h4>Your budget</h4><label>Up to <strong id="budget-value">${money(S.max)}</strong></label><input id="budget" type="range" min="${bounds.min}" max="${bounds.max}" step="any" value="${S.max}" ${bounds.empty||bounds.min===bounds.max?'disabled':''} aria-label="Budget / বাজেট"><div class="range-labels"><span id="budget-min">${money(bounds.min)}</span><span id="budget-max">${money(bounds.max)}</span></div></div><div class="filter-block"><h4>A little extra joy</h4><label class="radio-row"><input type="checkbox" id="sale-only" ${params.has('sale')?'checked':''}> On sale</label><label class="radio-row"><input type="checkbox" id="stock-only"> In stock only</label></div><div class="filter-note">${I('leaf')}<h4>Good things take care.</h4><p>Timeless pieces, chosen for the little moments.</p></div></aside>`}<section class="shop-results ${wishlist?'full-width':''}"><div class="results-toolbar"><span id="result-count"></span><label>Sort by <select id="sort-select"><option value="featured">Featured</option><option value="new">Newest arrivals</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="popular">Bestsellers</option></select></label></div><div class="product-grid" id="shop-products"></div><div id="pagination" class="pagination"></div></section></div></main>${footer()}`}
function renderProducts(){if(!$('#shop-products').length)return;syncBudget();const wish=location.hash.startsWith('#wishlist');let list=S.products.filter(p=>(wish?S.wish.includes(p.id):S.category==='All'||p.category===S.category)&&(!S.search||[p.name,p.name_bn,p.category,T(p.category),p.subcategory,T(p.subcategory)].join(' ').toLowerCase().includes(S.search.toLowerCase()))&&p.price<=S.max&&(!$('#sale-only').prop('checked')||p.old_price>p.price)&&(!$('#stock-only').prop('checked')||p.stock>0));if(S.sort==='low')list.sort((a,b)=>a.price-b.price);if(S.sort==='high')list.sort((a,b)=>b.price-a.price);if(S.sort==='new')list.sort((a,b)=>b.id-a.id);if(S.sort==='popular')list.sort((a,b)=>b.sales_units-a.sales_units||b.id-a.id);if(S.sort==='hot')list.sort((a,b)=>b.recent_units-a.recent_units||b.id-a.id);if(S.sort==='offers')list.sort((a,b)=>(b.old_price>b.price?1-b.price/b.old_price:0)-(a.old_price>a.price?1-a.price/a.old_price:0));if(S.sort==='picks')list.sort((a,b)=>b.featured-a.featured||b.id-a.id);$('#sort-select').val(S.sort);$('#result-count').html(`<strong>${list.length}</strong> thoughtful finds`);let pages=Math.ceil(list.length/12);S.page=Math.min(S.page,pages||1);$('#shop-products').html(list.slice((S.page-1)*12,S.page*12).map(card).join('')||`<div class="empty-state">${I(wish?'heart':'search')}<h3>${wish?'Your wishlist is waiting.':'No pieces found just yet.'}</h3><p>${wish?'Save something you love by tapping the little heart.':'Try another search or a wider price range.'}</p><a href="#shop" class="btn btn-dark">Explore the collection ${I('arrow')}</a></div>`);$('#pagination').html(pages>1?Array.from({length:pages},(_,i)=>`<button class="${S.page===i+1?'active':''}" data-page="${i+1}">${i+1}</button>`).join(''):'')}
function story(){return `${header()}<main class="story-page wrap"><div class="story-hero"><span class="eyebrow">THE BONON STORY</span><h1>Life is in the little things.<br><em>So are we.</em></h1><p>A familiar texture. A favorite corner. A thread that brings you home.</p></div><img class="story-image" src="/assets/hero.jpg" alt="The BONON everyday heritage collection"><div class="story-body"><span class="eyebrow">বুনন — THE ART OF WEAVING</span><h2>Rooted in Bangladesh.<br>Made for your everyday.</h2><p>BONON is a concept lifestyle store celebrating the warmth of our roots. We believe the pieces we surround ourselves with should have character, feel good, and belong in our everyday lives.</p><p>Our collection brings traditional silhouettes together with a modern sensibility. From a cotton saree to a softer home, each edit is an invitation to slow down and find beauty in the familiar.</p><div class="story-values">${[['leaf','Thoughtful by nature'],['heart','Made for real life'],['spark','Tradition, reimagined']].map(([i,t])=>`<div>${I(i)}<h3>${t}</h3></div>`).join('')}</div><a href="#shop" class="btn btn-dark">Find your everyday ${I('arrow')}</a></div></main>${footer()}`}
let lastFocus=null;
function modal(html,cls=''){lastFocus=document.activeElement;$('#overlay-root').html(`<div class="overlay"><div class="modal ${cls}" role="dialog" aria-modal="true" aria-label="BONON dialog"><button class="modal-close icon-button" data-action="close" aria-label="Close dialog">${I('close')}</button>${html}</div></div>`);$('body').addClass('modal-open');setTimeout(()=>$('.modal').find('input,button,a,select').filter(':visible').first().trigger('focus'),50)}
function closeModal(){$('#overlay-root').empty();$('body').removeClass('modal-open');if(lastFocus?.isConnected)lastFocus.focus()}
function baseLogin(register=false){if(S.user){location.hash=S.user.role==='admin'?'#admin':'#account';return}modal(`<div class="login-art"><div>${logo()}<h2>A little closer<br>to your roots.</h2><p>Your everyday favorites are waiting.</p></div></div><div class="login-content"><span class="eyebrow">WELCOME TO THE BONON WORLD</span><h2>${register?'Make yourself at home.':'Lovely to see you.'}</h2><p>${register?'A few details, a world of little joys.':'Sign in to your little corner of BONON.'}</p>${BOOT.demo&&!register?`<div class="demo-login"><div><span class="live-dot"></span> TAKE A LOOK AROUND <span>DEMO MODE</span></div><button data-demo="user">${I('user')}<span><strong>Explore as a customer</strong><small>Orders, wishlist & your account</small></span>${I('arrow')}</button><button data-demo="admin">${I('grid')}<span><strong>Step into the admin studio</strong><small>Analytics, products & store management</small></span>${I('arrow')}</button><small>One click. No password. All sample data.</small></div><div class="form-divider">or sign in with your email</div>`:''}<form id="auth-form" data-register="${register}">${register?'<label>Your name<input name="name" placeholder="Your full name" required minlength="2"></label>':''}<label>Email address<input name="email" type="email" placeholder="you@example.com" required></label><label>Password<input name="password" type="password" placeholder="${register?'At least 8 characters':'Your password'}" minlength="8" required></label><p class="form-error"></p><button class="btn btn-dark full">${register?'Create account':'Sign in'} ${I('arrow')}</button></form><p class="auth-toggle">${register?'Already part of the family?':'New around here?'} <button data-action="${register?'login':'register'}">${register?'Sign in':'Create an account'}</button></p></div>`,'login-modal')}
function baseProductModal(id){let p=product(id);if(!p)return;modal(`<div class="detail-image"><img src="${p.image}" alt="${esc(p.name)}">${p.tag?`<span class="product-tag">${esc(p.tag)}</span>`:''}</div><div class="detail-info"><span class="eyebrow">${esc(p.category)} / ${esc(p.subcategory)}</span><h2>${esc(p.name)}</h2><div class="detail-rating">★★★★★ <span>4.${7+p.id%3} · Sample ratings</span></div><div class="detail-price">${money(p.price)} ${p.old_price?`<del>${money(p.old_price)}</del><span>Save ${money(p.old_price-p.price)}</span>`:''}</div><p>${esc(p.description)}</p><div class="detail-option"><strong>Available palette</strong><div class="large-swatches">${p.colors.map(c=>`<i style="background:${c}"></i>`).join('')}<small>Illustrative colors</small></div></div><div class="detail-option"><div class="flex justify-between"><strong>Choose your size</strong><button class="text-link" data-info="Size guide">Size guide</button></div><div class="size-options">${p.sizes.map((s,i)=>`<button class="${i===0?'active':''}" data-size="${esc(s)}">${esc(s)}</button>`).join('')}</div></div><div class="stock-label"><i></i> ${p.stock>0?'In stock · Ready for a little joy':'Currently out of stock'}</div><div class="detail-buy"><input id="detail-qty" type="number" value="1" min="1" max="${Math.min(20,p.stock)}" aria-label="Quantity"><button class="btn btn-dark" data-add="${p.id}" ${p.stock<1?'disabled':''}>Add to bag ${I('bag')}</button><button class="btn btn-outline" data-wish="${p.id}" aria-label="Save to wishlist">${I('heart')}</button></div><div class="detail-perks"><span>${I('truck')} Delivery in 3–5 business days</span><span>${I('return')} Easy 7-day returns</span></div></div>`,'product-modal')}
function addCart(id,qty=1,size){const p=product(id);if(!p)return;if(!Number.isInteger(qty)||qty<1||qty>20)return toast('Choose a quantity between 1 and 20.');size=size||p.sizes[0];const existing=S.cart.filter(c=>c.id===id).reduce((sum,c)=>sum+c.qty,0);if(existing+qty>p.stock)return toast('That quantity is not available right now.');let item=S.cart.find(c=>c.id===id&&c.size===size);if(item){if(item.qty+qty>20)return toast('A maximum of 20 pieces per size.');item.qty+=qty}else S.cart.push({id,qty,size});save();closeModal();cartModal()}
function cartTotals(){const sub=S.cart.reduce((a,c)=>a+(product(c.id)?.price||0)*c.qty,0);let discount=S.coupon?Math.round(sub*S.coupon.percent/100):0;let shipping=sub>=Number(S.settings.free_shipping||3000)?0:Number(S.settings.shipping_fee||80);return {sub,discount,shipping,total:sub-discount+shipping}}
function summary(){const t=cartTotals();return `<div class="order-summary"><div><span>Subtotal</span><span>${money(t.sub)}</span></div>${t.discount?`<div class="discount-line"><span>${esc(S.coupon.code)} (${S.coupon.percent}% off)</span><span>−${money(t.discount)}</span></div>`:''}<div><span>Delivery</span><span>${t.shipping?money(t.shipping):'On us'}</span></div><div class="summary-total"><strong>Total</strong><strong>${money(t.total)}</strong></div></div>`}
function cartModal(){let t=cartTotals();modal(`<div class="drawer-title"><span class="eyebrow">A FEW GOOD FINDS</span><h2>Your shopping bag <small>(${S.cart.reduce((a,c)=>a+c.qty,0)})</small></h2></div>${S.cart.length?`<div class="free-shipping">${I('truck')}<span>${t.sub>=Number(S.settings.free_shipping)?'Lovely! Your delivery is on us.':`You’re ${money(Number(S.settings.free_shipping)-t.sub)} away from free delivery.`}</span><div><i style="width:${Math.min(100,t.sub/Number(S.settings.free_shipping)*100)}%"></i></div></div><div class="cart-items">${S.cart.map((c,i)=>{const p=product(c.id);return `<div class="cart-item"><img src="${p.image}" alt="${esc(p.name)}"><div><span>${esc(p.subcategory)}</span><h4>${esc(p.name)}</h4><small>Size: ${esc(c.size)}</small><div class="cart-item-bottom"><div class="qty-control"><button data-qty="${i}" data-change="-1" aria-label="Decrease quantity">−</button><span>${c.qty}</span><button data-qty="${i}" data-change="1" aria-label="Increase quantity">+</button></div><strong>${money(p.price*c.qty)}</strong></div></div><button class="remove-item" data-remove="${i}" aria-label="Remove ${esc(p.name)}">${I('close')}</button></div>`}).join('')}</div><div class="cart-footer">${summary()}<button class="btn btn-dark full" data-action="checkout">Continue to checkout ${I('arrow')}</button><button class="continue-link" data-action="close">A little more browsing</button><small>${I('shield')} Safe, secure, and thoughtfully packed.</small></div>`:`<div class="empty-state">${I('bag')}<h3>A little room for something lovely.</h3><p>Your bag is waiting for its first good find.</p><button class="btn btn-dark" data-action="browse">Explore the collection ${I('arrow')}</button></div>`}`,'cart-drawer')}
function baseCheckout(){closeModal();if(!S.user){toast('Sign in to save your order.');S.afterLogin='checkout';login();return}if(!S.cart.length){toast('Add something lovely to your bag first.');return}location.hash='#checkout'}
function baseCheckoutPage(){if(!S.user||!S.cart.length){setTimeout(()=>{location.hash='#shop';if(!S.user)login()},0);return ''}return `${header()}<main class="wrap checkout-page"><div class="breadcrumbs"><a href="#home">Home</a>${I('chevron')}<span>Checkout</span></div><div class="section-heading"><div><span class="eyebrow">JUST ONE MORE LITTLE STEP</span><h1>On its way to you.</h1></div><span class="secure-label">${I('shield')} Secure demo checkout</span></div><div class="checkout-grid"><section class="checkout-form panel"><h3>01 <span>Delivery details</span></h3><form id="checkout-form"><div class="form-grid"><label>Full name<input name="name" value="${esc(S.user.name)}" required></label><label>Phone number<input name="phone" value="${esc(S.user.phone)}" placeholder="01XXXXXXXXX" required pattern="[+0-9 ()\-]{8,20}"></label><label class="span-2">Delivery address<textarea name="address" rows="3" required placeholder="House, road, area, city">${esc(S.user.address)}</textarea></label><label class="span-2">Email address<input value="${esc(S.user.email)}" type="email" disabled></label></div><h3>02 <span>Payment method</span></h3><label class="payment-option"><input type="radio" name="payment" checked value="cod">${I('wallet')}<span><strong>Cash on delivery</strong><small>Pay when your little joys arrive.</small></span></label><div class="demo-notice">${I('shield')} This is a demo order. No payment will be taken and nothing will be shipped.</div><p class="form-error"></p><button class="btn btn-dark full">Place demo order ${I('arrow')}</button></form></section><aside class="panel checkout-summary"><h3>Your good finds <span>${S.cart.length} items</span></h3>${S.cart.map(c=>{const p=product(c.id);return `<div class="checkout-line"><img src="${p.image}" alt="${esc(p.name)}"><div><strong>${esc(p.name)}</strong><small>${esc(c.size)} · Qty ${c.qty}</small></div><span>${money(p.price*c.qty)}</span></div>`}).join('')}<form id="coupon-form" class="coupon-form"><input name="code" placeholder="A little discount code?" value="${esc(S.coupon?.code||'')}" aria-label="Discount code"><button class="btn btn-outline">Apply</button></form><small class="muted">Demo tip: use WELCOME10 for 10% off.</small><div id="checkout-totals">${summary()}</div></aside></div></main>${footer()}`}
const badge=status=>`<span class="status-badge status-${status.toLowerCase()}"><i></i>${esc(status)}</span>`;
function orderRows(orders,admin=false){return orders.map(o=>`<tr><td><button class="order-id" data-order="${o.id}">#BN-${String(o.id).padStart(4,'0')}</button><small>${date(o.created_at)}</small></td>${admin?`<td><div class="table-person"><span class="avatar">${esc(o.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><div>${esc(o.name)}<small>${esc(o.phone||o.email||'')}</small></div></div></td>`:''}<td>${o.items.length} ${o.items.length===1?'item':'items'}</td><td>${money(o.total)}</td><td>${badge(o.status)}</td><td><button class="icon-button" data-order="${o.id}" aria-label="View order">${I('chevron')}</button></td></tr>`).join('')}
function accountPage(){const u=S.user;let orders=S.orders;const tabs=[['overview','grid','My overview'],['orders','bag','My orders'],['tracking','truck','Track my parcel'],['wishlist','heart','My wishlist'],['profile','user','My details'],['address','location','Delivery address']];return `${header()}<main class="wrap account-page"><div class="breadcrumbs"><a href="#home">Home</a>${I('chevron')}<span>My account</span></div><div class="account-layout"><aside class="account-sidebar"><div class="profile-card"><span class="avatar big">${esc(u.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><h3>${esc(u.name)}</h3><small>${esc(u.phone)}</small><span class="member-label">${u.demo?'DEMO MEMBER':'BONON MEMBER'}</span></div><nav>${tabs.map(([id,ic,n])=>`<button data-account-tab="${id}" class="${S.accountTab===id?'active':''}">${I(ic)}${n}${I('chevron')}</button>`).join('')}<button data-action="logout">${I('logout')}Sign out</button></nav></aside><section class="account-main"><span class="eyebrow">YOUR LITTLE CORNER OF BONON</span><h1>${S.accountTab==='overview'?'Hello, '+esc(u.name.split(' ')[0])+'.':{orders:'Your good finds, on their way.',tracking:'Track your parcel, step by step.',profile:'A little about you.',address:'Your familiar doorstep.',wishlist:'Saved with love.'}[S.accountTab]}</h1><p class="muted">${S.accountTab==='overview'?'Lovely to have you here. Make yourself at home.':'Every little detail, all in one place.'}</p>${S.accountTab==='overview'?`<div class="account-stats">${[['bag',orders.length,'Total orders'],['truck',orders.filter(o=>['Pending','Processing','Shipped'].includes(o.status)).length,'On their way'],['heart',S.wish.length,'Saved favorites']].map(([ic,n,t])=>`<div class="panel">${I(ic)}<strong>${n}</strong><span>${t}</span></div>`).join('')}</div><div class="account-banner"><span>MADE FOR YOUR EVERYDAY</span><h2>Your next favorite is waiting.</h2><a class="text-link" href="#shop">Find something lovely ${I('arrow')}</a></div><div class="panel"><div class="panel-heading"><h3>Your latest orders</h3><button class="text-link" data-account-tab="orders">View all ${I('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Items</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${orderRows(orders.slice(0,3))||'<tr><td colspan="5">Your first good find is waiting in the collection.</td></tr>'}</tbody></table></div></div>`:S.accountTab==='orders'?`<div class="panel"><div class="panel-heading"><h3>All orders <span class="count-pill">${orders.length}</span></h3></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Items</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${orderRows(orders)||'<tr><td colspan="5">No orders yet. Explore the collection to get started.</td></tr>'}</tbody></table></div></div>`:S.accountTab==='tracking'?customerTrackingList(orders):S.accountTab==='wishlist'?`<div class="product-grid account-products">${S.products.filter(p=>S.wish.includes(p.id)).map(card).join('')||`<div class="empty-state">${I('heart')}<h3>Something lovely belongs here.</h3><a class="btn btn-dark" href="#shop">Find your favorites</a></div>`}</div>`:`<form id="profile-form" class="panel profile-form"><h3>${S.accountTab==='address'?'Where should your little joys arrive?':'Your details'}</h3><div class="form-grid"><label>Full name<input name="name" value="${esc(u.name)}" required></label><label>Phone number<input name="phone" value="${esc(u.phone)}" readonly></label><label class="span-2">Login phone<input value="${esc(u.phone)}" disabled><small>Your login phone cannot be changed here. Contact the store.</small></label><label class="span-2">Delivery address<textarea name="address" rows="4">${esc(u.address)}</textarea></label></div><p class="form-error"></p><button class="btn btn-dark">Save your details ${I('check')}</button></form>`}</section></div></main>${footer()}`}
function adminShell(){let tab=S.adminTab;const links=[['overview','grid','Overview'],['products','box','Products'],['orders','bag','Orders'],['customers','users','Customers'],['analytics','chart','Analytics'],['discounts','tag','Discounts']];return `<div class="admin-shell"><aside class="admin-sidebar">${logo()}<div class="studio-label">THE BONON STUDIO <span>ADMIN</span></div><span class="sidebar-label">WORKSPACE</span><nav>${links.map(([id,ic,n])=>`<a class="${tab===id?'active':''}" href="#admin/${id}">${I(ic)}${n}${id==='orders'?`<span class="nav-count">${S.admin.orders.filter(o=>o.status==='Pending').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-secondary"><span class="sidebar-label">MANAGE</span><nav><a class="${tab==='settings'?'active':''}" href="#admin/settings">${I('settings')}Store settings</a><a href="#home">${I('external')}View storefront</a></nav></div><div class="studio-note">${I('leaf')}<strong>A little care goes a long way.</strong><p>Make someone’s everyday a little more beautiful.</p></div><div class="admin-profile"><span class="avatar">AR</span><span><strong>${esc(S.user.name)}</strong><small>Store administrator</small></span><button data-action="logout" aria-label="Sign out">${I('logout')}</button></div></aside><div class="admin-workspace"><header class="admin-topbar"><div><button class="mobile-menu icon-button" data-action="admin-menu" aria-label="Open admin menu">${I('menu')}</button><span>Workspace</span>${I('chevron')}<strong>${{overview:'Overview',products:'Products',orders:'Orders',customers:'Customers',analytics:'Analytics',discounts:'Discounts',settings:'Store settings'}[tab]}</strong></div><div>${BOOT.demo?'<span class="demo-pill"><i></i> Demo workspace</span>':''}<button class="icon-button notification" data-action="notifications" aria-label="Notifications">${I('bell')}</button><span class="avatar">AR</span></div></header><main class="admin-main" id="admin-content">${adminContent()}</main><div class="admin-bottom"><span>Made with a little care. © 2026 BONON</span><span><i class="live-dot"></i> All systems feeling good</span></div></div></div>`}
function adminHeading(title,sub,buttons=''){return `<div class="admin-heading"><div><span class="eyebrow">THE BONON STUDIO</span><h1>${title}</h1><p>${sub}</p></div><div class="admin-heading-actions">${buttons}</div></div>`}
function filteredOrders(){const days=S.days||90;const anchor=Math.max(...S.admin.orders.map(o=>new Date(o.created_at.replace(' ','T')).getTime()),Date.now());return S.admin.orders.filter(o=>new Date(o.created_at.replace(' ','T')).getTime()>=anchor-days*86400000)}
function sparkline(i){const paths=['M0 30 12 26 22 30 33 15 43 20 54 12 65 16 77 5 90 8','M0 31 12 22 24 26 36 14 48 20 60 12 75 17 90 4','M0 31 15 32 30 20 42 24 53 10 68 17 80 8 90 12','M0 30 13 28 25 16 40 21 52 11 65 15 77 6 90 9'];return `<svg class="sparkline" viewBox="0 0 90 40"><path d="${paths[i]}" fill="none" stroke="${i===2?'#b58a55':'#71917c'}" stroke-width="2"/></svg>`}
function baseAdminContent(){let a=S.admin,t=S.adminTab;let exportButton=`<button class="btn btn-outline" data-action="export">${I('download')} Export report</button>`;
if(t==='overview'||t==='analytics'){
const orders=filteredOrders(),valid=orders.filter(o=>o.status!=='Cancelled'),rev=valid.reduce((sum,o)=>sum+o.total,0),sold=valid.reduce((sum,o)=>sum+o.items.reduce((n,l)=>n+l.quantity,0),0),average=valid.length?Math.round(rev/valid.length):0;
return `${adminHeading(t==='overview'?T('A good day to grow.','এগিয়ে যাওয়ার সুন্দর দিন।'):'Every number tells a story.',t==='overview'?"Here’s a little look at how your store is doing.":'Thoughtful insights for your next big little decision.',exportButton+`<select id="admin-range" aria-label="Report period"><option value="7" ${(S.days||90)===7?'selected':''}>Last 7 days</option><option value="30" ${(S.days||90)===30?'selected':''}>Last 30 days</option><option value="90" ${(S.days||90)===90?'selected':''}>Last 90 days</option></select>`)}<div class="demo-banner">${I('spark')}<span><strong>Your creative playground.</strong> ${BOOT.demo?'You’re exploring demo data. Try managing products, orders, and a little bit of everything.':'Welcome to your store workspace.'}</span><a href="#home">Visit store ${I('arrow')}</a></div><div class="stats-grid">${[['wallet','Total revenue',money(rev),'Excluding cancelled orders'],['bag','Total orders',orders.length,'Across your collection'],['users','Customers',new Set(orders.map(o=>o.user_id)).size,'Customers in this period'],['box','Products sold',sold,'Thoughtful pieces delivered']].map(([ic,title,val,desc],i)=>`<div class="stat-card"><div><span>${title}</span><span class="stat-icon">${I(ic)}</span></div><strong>${val}</strong><div class="stat-bottom"><span>${desc}</span>${sparkline(i)}</div></div>`).join('')}</div><div class="charts-grid"><section class="panel revenue-panel"><div class="panel-heading"><div><h3>Revenue overview</h3><p>A little progress, day by day.</p></div><span class="legend"><i></i> Revenue</span></div><div class="revenue-summary"><strong>${money(rev)}</strong><span>in the last ${S.days||90} days</span></div><div class="chart-container"><canvas id="revenue-chart"></canvas></div></section><section class="panel category-panel"><div class="panel-heading"><div><h3>What they’re loving</h3><p>Revenue by collection</p></div>${I('grid')}</div><div class="donut-container"><canvas id="category-chart"></canvas><div><small>TOTAL SALES</small><strong>${valid.length}</strong><span>happy little orders</span></div></div><div id="category-legend" class="category-legend"></div></section></div>${t==='analytics'?`<div class="analytics-lower"><section class="panel"><div class="panel-heading"><div><h3>Order fulfillment</h3><p>From your studio to their doorstep.</p></div></div><div class="chart-container"><canvas id="status-chart"></canvas></div></section><section class="panel insight-panel"><span class="eyebrow">THE LITTLE DETAILS</span><h3>Your store, at a glance.</h3><div><span>Average order value</span><strong>${money(average)}</strong></div><div><span>Active products</span><strong>${S.products.length}</strong></div><div><span>Available inventory</span><strong>${S.products.reduce((s,p)=>s+p.stock,0)}</strong></div><div><span>Newsletter subscribers</span><strong>${a.subscribers}</strong></div><div><span>Low-stock products</span><strong>${S.products.filter(p=>p.stock<10).length}</strong></div></section></div>`:`<div class="dashboard-lower"><section class="panel recent-orders"><div class="panel-heading"><div><h3>The latest good finds</h3><p>Your most recent orders.</p></div><a class="text-link" href="#admin/orders">All orders ${I('arrow')}</a></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${orderRows(a.orders.slice(0,5),true)}</tbody></table></div></section><section class="panel top-products"><div class="panel-heading"><div><h3>Little crowd-pleasers</h3><p>Top-selling products</p></div>${I('star')}</div>${topProducts(valid).slice(0,4).map((p,i)=>`<div class="top-product"><span class="rank">0${i+1}</span><img src="${p.image}" alt="${esc(p.name)}"><div><strong>${esc(p.name)}</strong><small>${p.qty} sold</small></div><span>${money(p.sales)}</span></div>`).join('')}<a href="#admin/analytics" class="text-link">Explore your insights ${I('arrow')}</a></section></div>`}`;
}
if(t==='products')return `${adminHeading('Thoughtfully stocked.','Every product is a little part of your story.',`<button class="btn btn-outline" data-action="export">${I('download')} Export</button><button class="btn btn-dark" data-action="add-product">${I('plus')} Add product</button>`)}<div class="mini-stats"><div><span>All products</span><strong>${S.products.length}</strong></div><div><span>In stock</span><strong>${S.products.filter(p=>p.stock>0).length}</strong></div><div><span>Low stock</span><strong>${S.products.filter(p=>p.stock<10&&p.stock>0).length}</strong></div><div><span>Collections</span><strong>5</strong></div></div><section class="panel"><div class="admin-table-tools"><div class="table-search">${I('search')}<input id="admin-search" placeholder="Search your products…" aria-label="Search products"></div><select id="admin-category"><option value="All">All collections</option>${['Women','Men','Kids','Home & Living','Accessories'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Collection</th><th>Price</th><th>Inventory</th><th>Status</th><th>Actions</th></tr></thead><tbody id="admin-table-body"></tbody></table></div><div class="table-footer"><span id="admin-result-count"></span><div id="admin-pagination" class="pagination"></div></div></section>`;
if(t==='orders')return `${adminHeading('A little joy, on its way.','Manage every order, from first click to familiar doorstep.',exportButton)}<section class="panel"><div id="admin-order-status-tabs">${adminOrderStatusTabs()}</div><div class="admin-table-tools"><div class="table-search">${I('search')}<input id="admin-search" placeholder="Search orders, customers or status…" aria-label="Search orders, customers or status"></div><select id="admin-status"><option value="All">All statuses</option>${adminOrderStatuses().map(status=>`<option value="${esc(status)}" ${status===(S.adminOrderStatus||'All')?'selected':''}>${T(status)}</option>`).join('')}</select></div><div class="table-wrap" id="admin-orders-table" role="tabpanel" aria-label="Orders"><table><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody id="admin-table-body"></tbody></table></div><div class="table-footer"><span id="admin-result-count"></span><div id="admin-pagination" class="pagination"></div></div></section>`;
if(t==='customers')return `${adminHeading('The people behind the orders.','Get to know your growing BONON community.',exportButton)}<div class="mini-stats"><div><span>Our community</span><strong>${a.customers.length}</strong></div><div><span>Returning customers</span><strong>${a.customers.filter(c=>c.orders>1).length}</strong></div><div><span>Newsletter subscribers</span><strong>${a.subscribers}</strong></div></div><section class="panel"><div class="admin-table-tools"><div class="table-search">${I('search')}<input id="admin-search" placeholder="Find a familiar name…" aria-label="Search customers"></div></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Location</th><th>Orders</th><th>Total spent</th><th></th></tr></thead><tbody id="admin-table-body"></tbody></table></div><div class="table-footer"><span id="admin-result-count"></span><div id="admin-pagination" class="pagination"></div></div></section>`;
if(t==='discounts')return `${adminHeading('A little something extra.','Create a good reason to come back for more.',`<button class="btn btn-dark" data-action="add-coupon">${I('plus')} Create discount</button>`)}<div class="coupon-grid">${a.coupons.map(c=>`<section class="coupon-card"><div class="coupon-top">${I('tag')}<span class="status-badge status-delivered"><i></i>Active</span></div><strong>${c.percent}<span>% OFF</span></strong><h3>${esc(c.code)}</h3><p>A little joy on every collection.<br>Applied to the order subtotal at checkout.</p><div><button class="text-link" data-edit-coupon="${c.id}">Edit discount ${I('edit')}</button><button class="icon-button" data-delete-coupon="${c.id}" aria-label="Delete discount">${I('trash')}</button></div></section>`).join('')}</div>`;
if(t==='settings')return `${adminHeading('Make yourself at home.','The little details that keep your store running beautifully.')}<form id="settings-form" class="settings-layout"><div><section class="panel settings-panel"><h3>Your store identity</h3><p>The name and voice your customers know.</p><div class="form-grid"><label>Store name<input name="store_name" value="${esc(a.settings.store_name)}" required></label><label>Support email<input type="email" name="store_email" value="${esc(a.settings.store_email)}" required></label><label class="span-2">Announcement bar<textarea name="announcement" rows="2" required>${esc(a.settings.announcement)}</textarea></label></div></section><section class="panel settings-panel"><h3>Delivery, thoughtfully done.</h3><p>Simple shipping rules for every order.</p><div class="form-grid"><label>Standard delivery fee (৳)<input type="number" name="shipping_fee" value="${esc(a.settings.shipping_fee)}" min="0" required></label><label>Free shipping above (৳)<input type="number" name="free_shipping" value="${esc(a.settings.free_shipping)}" min="0" required></label></div></section><p class="form-error"></p><button class="btn btn-dark">Save changes ${I('check')}</button></div><aside class="panel environment-panel">${I('shield')}<h3>Your environment</h3><span class="demo-pill"><i></i> ${BOOT.demo?'Demo mode is on':'Live environment'}</span><p>One-click logins and sample data are controlled on the server.</p><code>demo=${BOOT.demo?'true':'false'}</code><small>Update this value in your .env file. It cannot be changed from the browser.</small><hr><strong>Built with care</strong><p>PHP · SQLite · jQuery<br>Tailwind CSS · Chart.js</p><small>Live payment and delivery integrations are not configured.</small></aside></form>`;
return '';
}
function topProducts(orders){let m={};orders.forEach(o=>o.items.forEach(l=>{m[l.product_id]??={...l,qty:0,sales:0};m[l.product_id].qty+=l.quantity;m[l.product_id].sales+=l.quantity*l.price}));return Object.values(m).sort((a,b)=>b.qty-a.qty)}
Object.assign(L10N.dict,{'Search orders, customers or status…':'অর্ডার, ক্রেতা বা স্ট্যাটাস খুঁজুন…','Search orders, customers or status':'অর্ডার, ক্রেতা বা স্ট্যাটাস খুঁজুন','All statuses':'সব স্ট্যাটাস'});
const ADMIN_ORDER_STATUSES=['Pending','Processing','Shipped','Partially delivered','Delivered','Returned','Cancelled'];
function adminOrderStatuses(){return [...new Set([...ADMIN_ORDER_STATUSES,...(S.admin?.orders||[]).map(o=>o.status)])]}
function adminOrderStatusTabs(){const active=S.adminOrderStatus||'All',orders=S.admin?.orders||[];return `<div class="order-status-tabs" role="tablist" aria-label="${T('Filter orders by status','স্ট্যাটাস অনুযায়ী অর্ডার')}" aria-orientation="horizontal">${['All',...adminOrderStatuses()].map(status=>`<button type="button" role="tab" data-order-status="${esc(status)}" aria-selected="${status===active}" tabindex="${status===active?0:-1}" aria-controls="admin-orders-table" class="${status===active?'active':''}"><span>${status==='All'?T('All orders','সব অর্ডার'):T(status)}</span><span class="order-status-count">${status==='All'?orders.length:orders.filter(o=>o.status===status).length}</span></button>`).join('')}</div>`}
function adminOrderSearchText(o){const aliases={'Pending':'pending অপেক্ষমাণ পেন্ডিং','Processing':'processing প্রক্রিয়াধীন প্রসেসিং','Shipped':'shipped shipping in transit out for delivery শিপিং শিপড পাঠানো হয়েছে','Partially delivered':'partially delivered partial আংশিক ডেলিভারি','Delivered':'delivered ডেলিভারড ডেলিভারি হয়েছে','Returned':'returned return ফেরত এসেছে','Cancelled':'cancelled canceled বাতিল'};return ['#BN-'+String(o.id).padStart(4,'0'),o.name,o.phone,o.email||'',o.status,T(o.status),aliases[o.status]||''].join(' ').toLowerCase()}
function selectAdminOrderStatus(status){S.adminOrderStatus=status==='All'||adminOrderStatuses().includes(status)?status:'All';S.adminPage=1;$('#admin-status').val(S.adminOrderStatus);renderAdminTable()}
function renderAdminTable(){if(!$('#admin-table-body').length)return;const q=($('#admin-search').val()||'').trim().toLowerCase(),tab=S.adminTab;let rows=[],data=[];
if(tab==='products'){data=S.products.filter(p=>(p.name+' '+p.id).toLowerCase().includes(q)&&(!$('#admin-category').val()||$('#admin-category').val()==='All'||p.category===$('#admin-category').val())).sort((a,b)=>Number(b.id)-Number(a.id));rows=data.map(p=>`<tr><td><div class="table-product"><img src="${p.image}" alt="${esc(p.name)}"><div><button data-edit-product="${p.id}">${esc(p.name)}</button><small>BN-${String(p.id).padStart(4,'0')} · ${esc(p.subcategory)}</small></div></div></td><td>${esc(p.category)}</td><td><strong>${money(p.price)}</strong>${p.old_price?`<small><del>${money(p.old_price)}</del></small>`:''}</td><td><span class="inventory ${p.stock<10?'low':''}"><i></i>${p.stock} available</span></td><td>${badge(p.stock>0?'Active':'Soldout')}</td><td><div class="table-actions"><button data-edit-product="${p.id}" aria-label="Edit product">${I('edit')}</button><button data-delete-product="${p.id}" aria-label="Delete product">${I('trash')}</button></div></td></tr>`)}
if(tab==='orders'){const status=S.adminOrderStatus||'All';$('#admin-status').val(status);$('#admin-order-status-tabs').html(adminOrderStatusTabs());data=S.admin.orders.filter(o=>adminOrderSearchText(o).includes(q)&&(status==='All'||o.status===status));rows=data.map(o=>orderRows([o],true))}
if(tab==='customers'){data=S.admin.customers.filter(c=>(c.name+' '+c.phone+' '+(c.email||'')+' '+c.address).toLowerCase().includes(q));rows=data.map(c=>`<tr><td><div class="table-person"><span class="avatar">${esc(c.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><div><button data-customer="${c.id}">${esc(c.name)}</button><small>${esc(c.phone||c.email||'')}</small></div></div></td><td>${esc(c.address||'Not provided')}</td><td>${c.orders}</td><td><strong>${money(c.spent)}</strong></td><td><button class="icon-button" data-customer="${c.id}" aria-label="View customer">${I('chevron')}</button></td></tr>`)}
const pg=Math.max(1,Math.min(S.adminPage||1,Math.max(1,Math.ceil(data.length/10))));S.adminPage=pg;$('#admin-table-body').html(rows.slice((pg-1)*10,pg*10).join('')||'<tr><td colspan="6" class="table-empty">No results. Try a different search.</td></tr>');$('#admin-result-count').text(`Showing ${data.length?((pg-1)*10+1):0}–${Math.min(pg*10,data.length)} of ${data.length}`);$('#admin-pagination').html(Array.from({length:Math.ceil(data.length/10)},(_,i)=>`<button data-admin-page="${i+1}" class="${pg===i+1?'active':''}">${i+1}</button>`).join(''));
}
function renderCharts(){
 if(!$('#revenue-chart').length)return;
 const orders=filteredOrders().filter(o=>o.status!=='Cancelled');
 const colors=['#3f5b49','#819783','#c8b38b','#d3b7a9','#b7c1bb'];
 const cats=['Women','Men','Kids','Home & Living','Accessories'];
 const totals=cats.map(cat=>orders.reduce((s,o)=>s+o.items.filter(l=>product(l.product_id)?.category===cat).reduce((n,l)=>n+l.price*l.quantity,0),0));
 const total=totals.reduce((a,b)=>a+b,0);
 $('#category-legend').html(cats.map((c,i)=>`<div><span><i style="background:${colors[i]}"></i>${c}</span><strong>${total?Math.round(totals[i]/total*100):0}%</strong></div>`).join(''));
 const days=S.days||90,steps=days===7?7:days===30?10:12;
 const anchor=Math.max(...S.admin.orders.map(o=>new Date(o.created_at.replace(' ','T')).getTime()),Date.now());
 const start=anchor-days*86400000,interval=days*86400000/steps;
 const labels=[],values=[];
 for(let i=0;i<steps;i++){
  const min=start+i*interval,max=min+interval;
  labels.push(new Date(min).toLocaleDateString(L10N.lang==='bn'?'bn-BD':'en-GB',{day:'numeric',month:'short'}));
  values.push(orders.filter(o=>{const t=new Date(o.created_at.replace(' ','T')).getTime();return t>=min&&t<=max}).reduce((s,o)=>s+o.total,0));
 }
 Chart.defaults.font.family='DM Sans, sans-serif';Chart.defaults.color='#92988f';
 const ctx=document.getElementById('revenue-chart').getContext('2d'),gradient=ctx.createLinearGradient(0,0,0,260);
 gradient.addColorStop(0,'rgba(104,140,114,.25)');gradient.addColorStop(1,'rgba(104,140,114,0)');
 S.charts.push(new Chart(ctx,{
  type:'line',data:{labels,datasets:[{label:T('Revenue'),data:values,borderColor:'#52785f',borderWidth:2.5,backgroundColor:gradient,fill:true,tension:.38,pointRadius:0,pointHoverRadius:5}]},
  options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>money(c.parsed.y)}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{maxTicksLimit:7,font:{size:10}}},y:{grid:{color:'#f0f1ee'},border:{display:false},ticks:{maxTicksLimit:5,callback:v=>'৳'+(v>=1000?v/1000+'k':v),font:{size:10}}}}}
 }));
 S.charts.push(new Chart(document.getElementById('category-chart'),{
  type:'doughnut',data:{labels:cats.map(c=>T(c)),datasets:[{data:totals,backgroundColor:colors,borderWidth:4,borderColor:'#fff',borderRadius:4,hoverOffset:4}]},
  options:{responsive:true,maintainAspectRatio:false,cutout:'79%',plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>`${c.label}: ${money(c.parsed)}`}}}}
 }));
 if($('#status-chart').length)S.charts.push(new Chart(document.getElementById('status-chart'),{
  type:'bar',data:{labels:['Pending','Processing','Shipped','Delivered','Cancelled'].map(c=>T(c)),datasets:[{label:T('Orders'),data:['Pending','Processing','Shipped','Delivered','Cancelled'].map(st=>filteredOrders().filter(o=>o.status===st).length),backgroundColor:['#d2b77d','#abb99f','#8b9daf','#4f7057','#d6a69b'],borderRadius:5,barThickness:38}]},
  options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#f0f1ee'}}}}
 }));
}
function baseProductEditor(id){const p=product(id)||{name:'',category:'Women',subcategory:'Sarees',price:1490,old_price:0,stock:25,image:'/assets/saree-1.jpg',description:'',tag:'New arrival',sizes:['Standard']};modal(`<div class="editor-header"><span class="eyebrow">YOUR COLLECTION, YOUR STORY</span><h2>${id?'A little refinement.':'Something new to love.'}</h2><p>${id?'Update the details of this good find.':'Add a thoughtful piece to your collection.'}</p></div><form id="product-form" data-id="${id||0}"><div class="form-grid"><label class="span-2">Product name<input name="name" value="${esc(p.name)}" required minlength="3"></label><label>Collection<select name="category">${['Women','Men','Kids','Home & Living','Accessories'].map(c=>`<option ${c===p.category?'selected':''}>${c}</option>`).join('')}</select></label><label>Product type<input name="subcategory" value="${esc(p.subcategory)}" required></label><label>Price (৳)<input name="price" type="number" min="1" value="${p.price}" required></label><label>Compare-at price (৳)<input name="old_price" type="number" min="0" value="${p.old_price}"></label><label>Available inventory<input name="stock" type="number" min="0" value="${p.stock}" required></label><label>Label<select name="tag"><option value="">No label</option>${['New arrival','Bestseller'].map(c=>`<option ${p.tag===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Sizes (comma-separated)<input name="sizes" value="${esc(p.sizes.join(', '))}" required></label><label>Catalog image<select name="image">${[...new Set(S.products.map(p=>p.image))].map(img=>`<option value="${img}" ${img===p.image?'selected':''}>${img.split('/').pop().replace('.jpg','')}</option>`).join('')}</select></label><label class="span-2">The little details<textarea name="description" rows="3">${esc(p.description)}</textarea></label></div><p class="form-error"></p><div class="form-actions"><button type="button" class="btn btn-outline" data-action="close">Cancel</button><button class="btn btn-dark">${id?'Save changes':'Add product'} ${I('check')}</button></div></form>`,'editor-modal')}
function baseOrderDetail(id){const admin=location.hash.startsWith('#admin'),o=(admin?S.admin.orders:S.orders).find(o=>o.id==id);if(!o)return;modal(`<div class="editor-header"><span class="eyebrow">A LITTLE JOY, ON ITS WAY</span><h2>Order #BN-${String(o.id).padStart(4,'0')}</h2><p>${date(o.created_at)} ${badge(o.status)}</p></div><div class="order-progress">${['Pending','Processing','Shipped','Delivered'].map((st,i)=>`<div class="${['Pending','Processing','Shipped','Delivered'].indexOf(o.status)>=i?'complete':''}"><i>${I(i===3?'check':['bag','box','truck'][i])}</i><span>${st}</span></div>`).join('')}</div><div class="order-detail-lines">${o.items.map(l=>`<div class="checkout-line"><img src="${l.image}" alt="${esc(l.name)}"><div><strong>${esc(l.name)}</strong><small>${esc(l.size)} · Qty ${l.quantity}</small></div><strong>${money(l.price*l.quantity)}</strong></div>`).join('')}</div><div class="delivery-detail"><div><h4>Delivery to</h4><strong>${esc(o.name)}</strong><p>${esc(o.address)}<br>${esc(o.phone)}</p></div><div><h4>Order total</h4><strong>${money(o.total)}</strong><p>Delivery: ${money(o.shipping)}<br>Discount: ${money(o.discount)}</p></div></div>${admin?`<form id="status-form" data-id="${o.id}" class="status-form"><label>Update order status<select name="status">${['Pending','Processing','Shipped','Delivered','Cancelled'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn btn-dark">Save status ${I('check')}</button><p class="form-error"></p></form>`:'<div class="demo-notice">This is a sample order. No real delivery is scheduled.</div>'}`,'editor-modal')}
function couponEditor(id){const c=S.admin.coupons.find(c=>c.id==id)||{code:'',percent:10};modal(`<div class="editor-header"><span class="eyebrow">A LITTLE EXTRA JOY</span><h2>${id?'Refine your offer.':'Make their day.'}</h2></div><form id="discount-form"><label>Discount code<input name="code" value="${esc(c.code)}" placeholder="SOMETHINGLOVELY" required pattern="[A-Za-z0-9_-]{3,24}" ${id?'readonly':''}></label><label>Percentage off<input name="percent" type="number" value="${c.percent}" min="1" max="70" required></label><p class="muted">Applies to all collections. Shipping is not discounted.</p><p class="form-error"></p><button class="btn btn-dark full">Save discount ${I('check')}</button></form>`,'small-modal')}
async function baseRender(){S.charts.forEach(c=>c.destroy());S.charts=[];const hash=location.hash||'#home';closeModal();try{if(hash.startsWith('#admin')){if(!S.user||S.user.role!=='admin'){location.hash='#home';setTimeout(()=>{if(!S.user)login();else toast('This workspace is for store administrators.')},80);return}S.adminTab=hash.split('/')[1]||'overview';if(!['overview','products','orders','customers','analytics','discounts','settings'].includes(S.adminTab))S.adminTab='overview';S.admin=await api('admin');S.adminPage=1;$('#app').html(adminShell());renderAdminTable();renderCharts();document.title='BONON Studio — '+S.adminTab.charAt(0).toUpperCase()+S.adminTab.slice(1)}else if(hash.startsWith('#account')){if(!S.user){location.hash='#home';setTimeout(login,80);return}S.orders=(await api('my-orders')).orders;$('#app').html(accountPage());document.title='Your little corner — BONON'}else{let html=hash.startsWith('#shop')?shop():hash.startsWith('#wishlist')?shop(true):hash==='#story'?story():hash==='#checkout'?checkoutPage():home();$('#app').html(html);renderProducts();document.title='BONON — A little closer to your roots'}save();window.scrollTo(0,0)}catch(e){fail(e);$('#app').html(`<div class="empty-state"><h2>A little pause.</h2><p>We couldn’t load the store. Please try again.</p><button class="btn btn-dark" onclick="location.reload()">Try again</button></div>`)}}
async function adminReload(){await refresh();await render()}
function formData(el){return Object.fromEntries(new FormData(el).entries())}
function submitting(form,on){$(form).find('button[type=submit],button:not([type])').prop('disabled',on);$(form).find('.form-error').text('')}
function confirmAction(title,body,callback){modal(`<div class="confirm-icon">${I('trash')}</div><h2>${esc(title)}</h2><p>${esc(body)}</p><div class="form-actions"><button class="btn btn-outline" data-action="close">Keep it</button><button id="confirm-action" class="btn btn-dark">Yes, remove it</button></div>`,'small-modal');$('#confirm-action').one('click',async function(){this.disabled=true;try{await callback();closeModal();await adminReload()}catch(e){fail(e);this.disabled=false}})}
const info={
'Delivery & returns':'Our concept delivery policy: standard delivery across Bangladesh in 3–5 business days. Delivery is ৳'+Number(S.settings.shipping_fee||80)+', free above ৳'+Number(S.settings.free_shipping||3000)+'. Items may be returned within 7 days if unused with original packaging. This is a demonstration storefront: no real shipments or returns are processed.',
'Size guide':'Panjabi and shirts — chest measurements: S: 38 inches, M: 40 inches, L: 42 inches, XL: 44 inches, XXL: 46 inches. Kids sizes in this demo are illustrative; do not use these measurements for a real purchase. Sarees, home textiles, and accessories use Standard sizing. Please check with the store before ordering.',
'Privacy policy':'This demo stores account details and orders in a MySQL database, uses a session cookie for sign-in, and saves your shopping bag and wishlist in your browser. Newsletter emails are saved locally; no email is sent. Use sample information only. Demo accounts are shared. Contact the store administrator to remove data.',
'Terms of use':'BONON is a demonstration commerce experience. Products, ratings, discounts, order history and business metrics are sample content, not claims about a real trading business. Placing an order creates a local demo record only. No payment is charged. Product images from reference stores are used for this private prototype and require permission or replacement before commercial use.',
'Care guide':'A little care goes a long way. Wash cotton pieces gently with like colors, using cool water and mild detergent. Dry in the shade. Iron on a suitable low setting. Always follow the item’s actual care label. Store jewellery away from water, and wipe bags clean with a soft cloth.',
'Contact us':'We’re here for the little things. Reach our concept store at '+(S.settings.store_email||'hello@bonon.demo')+'. This is a demo email address, not a monitored support service. You can explore your orders and delivery details in My account.'};
function showInfo(title){modal(`<span class="eyebrow">HERE FOR THE LITTLE THINGS</span><h2>${esc(title)}</h2><p class="info-text">${esc(info[title]||'More little stories are on their way.')}</p><button class="btn btn-dark" data-action="close">Got it ${I('check')}</button>`,'small-modal')}
function exportData(){let data=S.adminTab==='products'?S.products.map(p=>({id:p.id,name:p.name,category:p.category,price:p.price,stock:p.stock})):S.adminTab==='customers'?S.admin.customers.map(c=>({name:c.name,email:c.email,orders:c.orders,total_spent:c.spent})):S.admin.orders.map(o=>({id:o.id,customer:o.name,date:o.created_at,total:o.total,status:o.status}));if(!data.length)return toast('There is no data to export yet.');const safe=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const csv='\uFEFF'+[Object.keys(data[0]).map(safe).join(','),...data.map(row=>Object.values(row).map(safe).join(','))].join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=`bonon-${S.adminTab}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your report is ready.')}
$(document).on('click','[data-action]',async function(){const act=$(this).data('action');if(act==='close')closeModal();if(act==='login')login();if(act==='register')login(true);if(act==='account'){if(S.user)location.hash=S.user.role==='admin'?'#admin':'#account';else login()}if(act==='cart')cartModal();if(act==='checkout')checkout();if(act==='browse'){closeModal();location.hash='#shop'}if(act==='logout'){await api('logout',{});S.user=null;S.accountTab='overview';location.hash='#home';await render();toast('See you again soon.')}if(act==='reset-filters'){S.search='';S.category='All';syncBudget(true);S.sort='featured';S.page=1;$('input[name=category][value=All]').prop('checked',true);$('#sale-only,#stock-only').prop('checked',false);renderProducts()}if(act==='mobile-menu')$('.store-nav').toggleClass('is-open');if(act==='admin-menu')$('.admin-sidebar').toggleClass('is-open');if(act==='add-product')productEditor();if(act==='add-coupon')couponEditor();if(act==='export')exportData();if(act==='notifications'){const low=S.products.filter(p=>p.stock<10);modal(`<span class="eyebrow">A LITTLE HEADS-UP</span><h2>Your studio updates.</h2><div class="notification-item">${I('bag')}<div><strong>${S.admin.orders.filter(o=>o.status==='Pending').length} orders need a little attention.</strong><p>Review pending orders and get them ready.</p><a href="#admin/orders" class="text-link">See orders ${I('arrow')}</a></div></div><div class="notification-item">${I('box')}<div><strong>${low.length} products are running low.</strong><p>Keep your favorites thoughtfully stocked.</p><a href="#admin/products" class="text-link">Manage products ${I('arrow')}</a></div></div>`,'small-modal')}});
$(document).on('click','.overlay',function(e){if(e.target===this)closeModal()});
$(document).on('keydown',function(e){if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal').length){let f=$('.modal').find('a,button,input,select,textarea,[tabindex="0"]').filter(':visible:not(:disabled)');if(!f.length)return;if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.last().trigger('focus')}if(!e.shiftKey&&document.activeElement===f[f.length-1]){e.preventDefault();f.first().trigger('focus')}}});
$(document).on('click','[data-demo]',async function(){let role=$(this).data('demo');$('[data-demo]').prop('disabled',true);try{S.user=(await api('demo-login',{role})).user;closeModal();if(S.afterLogin==='checkout'&&role==='user'){S.afterLogin=null;location.hash='#checkout'}else{S.afterLogin=null;location.hash=role==='admin'?'#admin':'#account'}toast(role==='admin'?'Welcome to your creative studio.':'Make yourself at home, Nadia.')}catch(e){fail(e);$('[data-demo]').prop('disabled',false)}});
$(document).on('submit','#auth-form',function(e){e.preventDefault();handleAuthSubmit(this)});
$(document).on('submit','#search-form',function(e){e.preventDefault();const q=$(this).find('input').val().trim();S.shopInit=false;location.hash='#shop?q='+encodeURIComponent(q);if(location.hash==='#shop?q='+encodeURIComponent(q))render()});
$(document).on('click','[data-tab]',function(){S.tab=$(this).data('tab');$('.collection-tabs button').removeClass('active');$(this).addClass('active');$('#featured-products').hide().html(S.products.filter(p=>S.tab==='All'||p.category===S.tab).slice(0,4).map(card).join('')).fadeIn(220)});
$(document).on('click','[data-product]',function(){productModal(+$(this).data('product'))});
$(document).on('click','[data-wish]',function(){const id=+$(this).data('wish');if(S.wish.includes(id)){S.wish=S.wish.filter(x=>x!==id);toast('Removed from your saved favorites.')}else{S.wish.push(id);toast('A little favorite, saved.')}save();$(`[data-wish="${id}"]`).toggleClass('selected',S.wish.includes(id));if(location.hash.startsWith('#wishlist'))renderProducts()});
$(document).on('click','[data-size]',function(){$('.size-options button').removeClass('active');$(this).addClass('active')});
$(document).on('click','[data-add]',function(){addCart(+$(this).data('add'),+$('#detail-qty').val(),String($('.size-options .active').data('size')))});
$(document).on('click','[data-qty]',function(){let i=+$(this).data('qty'),delta=+$(this).data('change'),c=S.cart[i];let count=S.cart.filter(x=>x.id===c.id).reduce((a,b)=>a+b.qty,0);if(delta>0&&(count>=product(c.id).stock||c.qty>=20))return toast('That quantity is not available.');c.qty+=delta;if(c.qty<=0)S.cart.splice(i,1);save();cartModal()});
$(document).on('click','[data-remove]',function(){S.cart.splice(+$(this).data('remove'),1);save();cartModal()});
$(document).on('change','input[name=category]',function(){S.category=this.value;S.page=1;renderProducts()});
$(document).on('input','#budget',function(){S.max=+this.value;S.page=1;$('#budget-value').text(money(S.max));renderProducts()});
$(document).on('change','#sort-select,#sale-only,#stock-only',function(){S.sort=$('#sort-select').val();S.page=1;renderProducts()});
$(document).on('click','[data-page]',function(){S.page=+$(this).data('page');renderProducts();document.querySelector('.shop-results').scrollIntoView({behavior:'smooth'})});
$(document).on('submit','#coupon-form',async function(e){e.preventDefault();try{S.coupon=(await api('coupon&code='+encodeURIComponent(this.code.value))).coupon;$('#checkout-totals').html(summary());toast('A little extra joy: discount applied.')}catch(e){S.coupon=null;$('#checkout-totals').html(summary());fail(e)}});
$(document).on('submit','#checkout-form',function(e){e.preventDefault();handleCheckoutSubmit(this)});
$(document).on('submit','#newsletter-form',async function(e){e.preventDefault();submitting(this,true);try{const result=await api('subscribe',formData(this));this.reset();toast(result.message||'Your email preference has been saved.')}catch(e){fail(e)}finally{submitting(this,false)}});
$(document).on('click','[data-info]',function(){showInfo($(this).data('info'))});
$(document).on('click','[data-account-tab]',async function(){S.accountTab=$(this).data('account-tab');await render()});
$(document).on('submit','#profile-form',async function(e){e.preventDefault();submitting(this,true);try{S.user=(await api('profile',formData(this))).user;await render();toast('Your details feel right at home.')}catch(e){fail(e);submitting(this,false)}});
$(document).on('click','[data-order]',function(){orderDetail(+$(this).data('order'))});
$(document).on('click','[data-edit-product]',function(){productEditor(+$(this).data('edit-product'))});
$(document).on('click','[data-delete-product]',function(){let id=+$(this).data('delete-product');confirmAction('Make a little room?','This product will be removed from the storefront. Existing orders will not be changed.',async()=>{await api('product-delete',{id});toast('Product removed from the collection.')})});
$(document).on('submit','#product-form',async function(e){e.preventDefault();submitting(this,true);try{await api('product-save',{...formData(this),id:+$(this).data('id')});closeModal();await adminReload();toast('Your collection has been updated.')}catch(e){fail(e);submitting(this,false)}});
$(document).on('input','#admin-search',function(){S.adminPage=1;renderAdminTable()});
$(document).on('change','#admin-category',function(){S.adminPage=1;renderAdminTable()}).on('change','#admin-status',function(){selectAdminOrderStatus(this.value)}).on('click','[data-order-status]',function(){const status=this.dataset.orderStatus;selectAdminOrderStatus(status);$('[data-order-status]').filter(function(){return this.dataset.orderStatus===status}).trigger('focus')}).on('keydown','[data-order-status]',function(e){const statuses=['All',...adminOrderStatuses()];let i=statuses.indexOf(this.dataset.orderStatus);if(e.key==='ArrowRight')i=(i+1)%statuses.length;else if(e.key==='ArrowLeft')i=(i-1+statuses.length)%statuses.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=statuses.length-1;else return;e.preventDefault();selectAdminOrderStatus(statuses[i]);$('[data-order-status]').filter(function(){return this.dataset.orderStatus===statuses[i]}).trigger('focus')});
$(document).on('click','[data-admin-page]',function(){S.adminPage=+$(this).data('admin-page');renderAdminTable()});
$(document).on('change','#admin-range',async function(){S.days=+this.value;await render()});
$(document).on('submit','#status-form',async function(e){e.preventDefault();submitting(this,true);try{await api('order-status',{id:+$(this).data('id'),status:this.status.value,courier:this.courier?.value||'',tracking_number:this.tracking_number?.value||''});closeModal();await adminReload();toast('Order status updated.')}catch(e){fail(e);submitting(this,false)}});
$(document).on('click','[data-customer]',function(){let c=S.admin.customers.find(c=>c.id==$(this).data('customer'));modal(`<div class="customer-detail"><span class="avatar big">${esc(c.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><span class="eyebrow">THE BONON COMMUNITY</span><h2>${esc(c.name)}</h2><p>${esc(c.phone||c.email||'')}</p><div class="customer-totals"><div><strong>${c.orders}</strong><span>Orders</span></div><div><strong>${money(c.spent)}</strong><span>Total spent</span></div></div><div class="delivery-detail"><div><h4>Delivery address</h4><p>${esc(c.address||'Not provided')}</p><h4>Phone</h4><p>${esc(c.phone||'Not provided')}</p></div></div></div>`,'small-modal')});
$(document).on('click','[data-edit-coupon]',function(){couponEditor(+$(this).data('edit-coupon'))});
$(document).on('click','[data-delete-coupon]',function(){const id=+$(this).data('delete-coupon');confirmAction('Retire this little offer?','This discount code will no longer be available at checkout.',async()=>{await api('coupon-delete',{id});toast('Discount removed.')})});
$(document).on('submit','#discount-form',async function(e){e.preventDefault();submitting(this,true);try{await api('coupon-save',formData(this));closeModal();await adminReload();toast('A little extra joy, ready to share.')}catch(e){fail(e);submitting(this,false)}});
$(document).on('submit','#settings-form',async function(e){e.preventDefault();submitting(this,true);try{await api('settings-save',formData(this));await adminReload();toast('Your store settings are saved.')}catch(e){fail(e);submitting(this,false)}});

